typedef int (*ApiResult)(void* context, int status);

// Function definition matching the signature
static int HandleError(void* ctx, int s) {
    *(int*)ctx = s;
    return s == 0;
}

// Function pointer registration
ApiResult CurrentCallback = HandleError;

int last_status = -1;

// Dynamic invocation
CurrentCallback(&last_status, 404);

// last_status is now 404



typedef float (*FilterFunc)(float input);

float LowPass(float i) { return i * 0.5f; }
float HighPass(float i) { return i * 0.9f; }

// Dispatch Table (Dynamic V-Table)
FilterFunc Filters[] = {
    LowPass,
    HighPass
};

enum FilterType { LP, HP };

// Dispatch using enumeration index
float result_hp = Filters[HP](100.0f);
float result_lp = Filters[LP](100.0f);



struct VTable {
    void* context;
    int (*connect)(void* ctx, const char* addr);
    int (*send)(void* ctx, const char* data);
    void (*close)(void* ctx);
};

int NetConnect(void* c, const char* a);

// Setup implementation for a TCP handler
struct VTable TcpHandler = {
    .context = NULL, // allocated later
    .connect = NetConnect,
    .send = NULL, // filled by implementation
    .close = NULL
};

// Use the interface
int success = TcpHandler.connect(NULL, "127.0.0.1");
